public int findLargestSubstring(List<String> strings) {
    int maxLength = 0;
    for (String s : strings) {
        int length = s.length();
        if (length > maxLength) {
            maxLength = length;
        }
    }
    for (String s : strings) {
        int len = s.length();
        for (int i = 0; i <= len - maxLength; i++) {
