public int findLargestSubstring(List<String> strings) {
    // Find the longest common substring
    int longestCommonSubstringLength = 1;
    for (int i = 1; i < strings.size(); i++) {
        for (int j = 0; j < strings.get(i).length() - longestCommonSubstringLength; j++) {
            boolean substringFound = true;
            for (int k = 0; k < strings.get(i - 1).length(); k++) {
                if (strings.get(i - 1).charAt(k) != strings.get(i).charAt(j + k)) {
                    substringFound = false;
                    break;
                }
            }
            if (substringFound) {
                longestCommonSubstringLength++;
            }
        }
    }

    // Find the maximum length of any substring
    int maximumSubstringLength = 0;
    for (String string : strings) {
        if (maximumSubstringLength < string.length()) {
            maximumSubstringLength = string.length();
        }
    }

    // Return the maximum of longest common substring length and the maximum substring length
    return Math.max(longestCommonSubstringLength, maximumSubstringLength);
}
