        if (current[0] == end[0] && current[1] == end[1]) {
            return "can be travelled";
        }
        for (int[] path : paths) {
            int row = current[0] + path[0];
            int col = current[1] + path[1];
            if (row >= 0 && row < n && col >= 0 && col < n && !visited[row][col]) {
