public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n < 1 || start.length < 1 || end.length < 1 || paths.length != n) {
        return "cannot be travelled";
    }

    int startIndex = start[0] * n + start[1];
    int endIndex = end[0] * n + end[1];

    boolean[] visited = new boolean[n * n];
    for (int i = 0; i < n * n; i++) {
        visited[i] = false;
    }

    visited[startIndex] = true;
    Queue<Integer> queue = new LinkedList<>();
    queue.add(startIndex);

    while (!queue.isEmpty()) {
        int currIndex = queue.poll();
        if (currIndex == endIndex) {
            return "can be travelled";
        }
        for (int i = 0; i < paths.length; i++) {
            if (paths[currIndex][i] == 1 && !visited[i]) {
                visited[i] = true;
                queue.add(i);
            }
        }
    }

    return "cannot be travelled";
}
```

