public boolean canArrange(int[] arr, int k) {
    int n = arr.length;
    if (n % 2 == 1) return false;
    for (int i = 0; i < n / 2; i++) {
        boolean found = false;
        for (int j = n / 2; j < n; j++) {
            if ((arr[i] + arr[j]) % k == 0) {
                found = true;
                break;
            }
        }
        if (!found) return false;
    }
    return true;
