public boolean canArrange(int[] arr, int k) {
    int n = arr.length;
    if (n % 2 == 1) return false;
    int[] counts = new int[k];
    for (int i = 0; i < n; i++) {
        int sum = arr[i] + arr[(i + n/2) % n];
        if (sum % k != 0) return false;
        counts[sum % k]++;
    }
    int target = n/2;
    for (int count : counts) {
        if (count < target) return false;
    }
    return true;
}
