public boolean canArrange(int[] arr, int k) {
    int n = arr.length;
    int[] sum = new int[n];
    for (int i = 0; i < n; i++) {
        sum[i] = (arr[i] % k) + (i > 0 ? sum[i - 1] : 0);
    }
    int target = sum[n - 1] / 2;
    int[] dp = new int[target + 1];
    for (int i = 0; i < n; i++) {
        for (int j = target; j >= sum[i]; j--) {
            dp[j] += dp[j - sum[i]];
        }
    }
    return dp[target] > 0;
}
