public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialize variables
    int sourceNode = 0;
    int time = 0;
    boolean[] visited = new boolean[n];
    Stack<Integer> stack = new Stack<>();

    // Start from the source node and begin the traversal
    stack.push(sourceNode);
    visited[sourceNode] = true;
    while (!stack.isEmpty()) {
        // Take the node from the top of the stack and check if it has an apple
        int node = stack.pop();
        if (hasApple[node]) {
            // If the node has an apple, increment the time and return to the source node
            time++;
            break;
        }

        // If the node does not have an apple, add its neighbors to the stack and mark them as visited
        for (int neighbor : edges[node]) {
            if (!visited[neighbor]) {
                stack.push(neighbor);
                visited[neighbor] = true;
            }
        }
    }

    // If the source node has an apple, return the current time
    if (hasApple[sourceNode]) {
        return time;
    }

    // If the source node does not have an apple, the minimum time is the maximum depth of the tree
    int maxDepth = 0;
    for (int node : visited) {
        if (node > maxDepth) {
            maxDepth = node;
        }
    }

    // Increment the time by the maximum depth of the tree and return the result
    time += maxDepth;
    return time;
}
