public int findNumberOfLIS(int[] nums) {
    int n = nums.length;
    int[] dp = new int[n];
    int[] prev = new int[n];
    int[] next = new int[n];

    Arrays.fill(dp, 1);
    Arrays.fill(prev, -1);
    Arrays.fill(next, -1);

    for (int i = 1; i < n; i++) {
        for (int j = 0; j < i; j++) {
            if (nums[i] > nums[j]) {
                if (dp[i] < dp[j] + 1) {
                    dp[i] = dp[j] + 1;
                    prev[i] = j;
                }
                if (dp[i] == dp[j] + 1) {
                    next[i] = next[j];
                    next[j] = i;
                }
            }
        }
    }

    int maxLength = 0;
    int start = 0;
    for (int i = 0; i < n; i++) {
        if (dp[i] > maxLength) {
            maxLength = dp[i];
            start = i;
        }
    }

    List<Integer> ans = new ArrayList<>();
    for (int i = start; i != -1; i = next[i]) {
        ans.add(nums[i]);
    }
    Collections.reverse(ans);
    return ans.size();
}
