import java.util.ArrayList;

public class Solution {
    public int minOperations(int n) {
        // Initialize the array with the given length
        ArrayList<Integer> arr = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            arr.add((2 * i) + 1);
        }

        // Initialize the minimum number of operations to 0
        int minOperations = 0;

        // Loop through the array and compare adjacent elements
        for (int i = 0; i < n - 1; i++) {
            // If the adjacent elements are not equal, perform an operation to make them equal
            if (arr.get(i) != arr.get(i + 1)) {
                minOperations++;
                // Perform the operation by subtracting 1 from the first element and adding 1 to the second element
                arr.set(i, arr.get(i) - 1);
                arr.set(i + 1, arr.get(i + 1) + 1);
            }
        }

        // Return the minimum number of operations required
        return minOperations;
    }
}

