public int findMinFibonacciNumbers(int k) {
    int[] fib = {0, 1, 1};
    for (int i = 3; fib[i - 1] < k; i++) {
        fib[i] = fib[i - 1] + fib[i - 2];
    }
    int count = 0;
    while (k > 0) {
        count++;
        k -= fib[count];
    }
    return count;
}
