public int findMinFibonacciNumbers(int k) {
    int f1 = 1, f2 = 1, fn = 0;
    int count = 0;
    while (k > 0) {
        fn = f1 + f2;
        f1 = f2;
        f2 = fn;
        if (k-fn >= 0) {
            k -= fn;
            count++;
        }
    }
    return count;
