public class Solution {
    public int maxUniqueSplit(String s) {
        int n = s.length();
        int[] cnt = new int[n];
        char[] arr = s.toCharArray();

        // Calculate the frequency of each character
        for (int i = 0; i < n; i++) {
            cnt[i] = arr[i] - 'a' + 1;
        }

        // Calculate the maximum number of unique substrings
        int max = 1;
        int curr = 1;
        for (int i = 1; i < n; i++) {
