        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                horizDir[i][j] = j > 0 ? horizDir[i][j-1] + 1 : 1;
                vertiDir[i][j] = i > 0 ? vertiDir[i-1][j] + 1 : 1;
                diagDir[i+j][0] = i > 0 && j > 0 ? diagDir[i-1][j-1] + 1 : 1;
                antiDiagDir[i+j][0] = i > 0 && j > 0 ? antiDiagDir[i-1][j+1] + 1 : 1;
                maxLen = Math.max(maxLen, horizDir[i][j]);
                maxLen = Math.max(maxLen, vertiDir[i][j]);
                maxLen = Math.max(maxLen, diagDir[i+j][0]);
                maxLen = Math.max(maxLen, antiDiagDir[i+j][0]);
            }
        }
    }

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                if (i > 0 && j > 0 && horizDir[i][j] > Math.max(vertiDir[i-1][j], diagDir[i+j-1][0])) {
                    return Math.max(maxLen, horizDir[i][j] +  horizDir[i-1][j-1]);
                } else if (i > 0 && vertiDir[i][j] > diagDir[i+j-1][0]) {
