public static int squarePermutations(int[] A) {
    int n = A.length, res = 0;
    boolean[] vis = new boolean[n];
    for (int i = 0; i < n; i++) vis[i] = false;
    for (int i = 0; i < n; i++) {
        if (!vis[i]) {
            vis[i] = true;
            dfs(A, i, vis, 0, 0, 1, res);
        }
    }
    return res;
}

private static void dfs(int[] A, int u, boolean[] vis, int count, int sum, int mult, int[] res) {
    if (count == A.length) {
        res[0]++;
        return;
    }
    if (vis[u]) return;
    for (int i = 0; i < A.length; i++) {
        if (!vis[i]) {
            vis[i] = true;
            int newSum = sum + A[u] * A[i];
            int newCount = count + 1;
            int newMult = mult * A[i];
            dfs(A, i, vis, newCount, newSum, newMult, res);
            vis[i] = false;
            if (sum == 0) break;
        }
    }
}
