public static int minPerfectSquareSum(int n) {
    // Initialize the number of perfect square numbers needed to sum up to n as n itself
    int numPerfectSquares = n;
    // Initialize the current perfect square number as 1
    int currentPerfectSquare = 1;

    // Loop until the current perfect square is less than or equal to the square root of n
    while (currentPerfectSquare <= Math.sqrt(n)) {
        // If the current perfect square is a divisor of n, decrement the number of perfect square numbers needed
        if (n % currentPerfectSquare == 0) {
            numPerfectSquares--;
        }
        // Increment the current perfect square by 1
        currentPerfectSquare++;
    }

    // Return the minimum number of perfect square numbers needed to sum up to n
    return numPerfectSquares;
}

