    for (int i = 0; i < words.length; i++) {
        String word = words[i];
        char[] chars = word.toCharArray();
        sb.append(reverse(chars));
        if (i < words.length - 1) {
            sb.append(" ");
        }
    }
    return sb.toString();
}

private static String reverse(char[] chars) {
    StringBuilder sb = new StringBuilder();
    for (int i = chars.length - 1; i >= 0; i--) {
        sb.append(chars[i]);
    }
    return sb.toString();
}
